    expect(control.hasAttribute('data-filled')).toBe(true);
    expect(control.hasAttribute('data-dirty')).toBe(true);
  });

  it('B: unmount while focused does not latch data-focused on root', () => {
    function App({ show }: { show: boolean }) {
      return (
        <Field.Root data-testid="root">{show ? <Field.Control data-testid="control" /> : null}</Field.Root>
      );
    }
    const { rerender } = render(<App show />);
    const control = screen.getByTestId('control');
    act(() => control.focus());
    console.log('B focused attrs on root before unmount:', screen.getByTestId('root').getAttribute('data-focused'));
    rerender(<App show={false} />);
    console.log('B root attrs after unmount:', [...screen.getByTestId('root').attributes].map((a) => a.name).join(' '));
    expect(screen.getByTestId('root').hasAttribute('data-focused')).toBe(false);
  });

