        <Field.Root data-testid="root">
          <Field.Control
            data-testid="control"
            value={value}
            onValueChange={(next, details) => {
              details.cancel();
              setValue(next);
            }}
          />
        </Field.Root>
      );
    }
    render(<App />);
    const control = screen.getByTestId('control') as HTMLInputElement;
    fireEvent.change(control, { target: { value: 'z' } });
    console.log('C dirty after canceled-but-applied change:', control.hasAttribute('data-dirty'));
  });
});
EOF
